    /*
     * Add to the Tasks
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	DataPipeline
     */
    public DataPipeline addToTasks( UUID parentId, DataTask addTo ) {
	    LOGGER.info("handling AssignTasksToDataPipelineEvent - " );
	    
	    DataPipeline parentEntity = repository.findById(parentId).get();
	    DataTask child = registry.project( DataTask.class, addTo.getDataTaskId());
	    
	    parentEntity.getTasks().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

